#!/usr/bin/env bash
# Question 1: Control plane after maintenance. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

kubectl create namespace "${Q1_NS}" >/dev/null 2>&1 || kubectl get namespace "${Q1_NS}" >/dev/null
timeout 60 bash -c "until kubectl -n '${Q1_NS}' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
kubectl apply -f - <<EOF
apiVersion: apps/v1
kind: Deployment
metadata:
  name: web
  namespace: ${Q1_NS}
spec:
  replicas: 0
  selector:
    matchLabels: { app: web }
  template:
    metadata:
      labels: { app: web }
    spec:
      containers:
        - name: web
          image: nginx:1.27-alpine
          resources:
            requests: { cpu: 10m, memory: 16Mi }
EOF

case "${Q1_FAULT}" in
  apiserver-etcd-port)
    kubectl -n "${Q1_NS}" scale deployment/web --replicas=2
    if [[ "$(kubectl -n kube-system get pod kube-scheduler-controlplane -o jsonpath='{.status.conditions[?(@.type=="Ready")].status}' 2>/dev/null || true)" == True && "$(kubectl -n kube-system get pod kube-controller-manager-controlplane -o jsonpath='{.status.conditions[?(@.type=="Ready")].status}' 2>/dev/null || true)" == True ]]; then
      kubectl -n "${Q1_NS}" rollout status deployment/web --timeout=240s
    fi
    sed -i -E 's#^([[:space:]]*- --etcd-servers=https://127.0.0.1):2379$#\1:2380#' /etc/kubernetes/manifests/kube-apiserver.yaml
    grep -qE -- '- --etcd-servers=https://127.0.0.1:2380$' /etc/kubernetes/manifests/kube-apiserver.yaml || { echo "could not modify /etc/kubernetes/manifests/kube-apiserver.yaml" >&2; exit 1; }
    ;;
  apiserver-etcd-certfile)
    kubectl -n "${Q1_NS}" scale deployment/web --replicas=2
    if [[ "$(kubectl -n kube-system get pod kube-scheduler-controlplane -o jsonpath='{.status.conditions[?(@.type=="Ready")].status}' 2>/dev/null || true)" == True && "$(kubectl -n kube-system get pod kube-controller-manager-controlplane -o jsonpath='{.status.conditions[?(@.type=="Ready")].status}' 2>/dev/null || true)" == True ]]; then
      kubectl -n "${Q1_NS}" rollout status deployment/web --timeout=240s
    fi
    sed -i -E 's#^([[:space:]]*- --etcd-certfile=)/etc/kubernetes/pki/apiserver-etcd-client.crt$#\1/etc/kubernetes/pki/etcd/apiserver-etcd-client.crt#' /etc/kubernetes/manifests/kube-apiserver.yaml
    grep -qE -- '- --etcd-certfile=/etc/kubernetes/pki/etcd/apiserver-etcd-client.crt$' /etc/kubernetes/manifests/kube-apiserver.yaml || { echo "could not modify /etc/kubernetes/manifests/kube-apiserver.yaml" >&2; exit 1; }
    ;;
  apiserver-etcd-flags)
    kubectl -n "${Q1_NS}" scale deployment/web --replicas=2
    if [[ "$(kubectl -n kube-system get pod kube-scheduler-controlplane -o jsonpath='{.status.conditions[?(@.type=="Ready")].status}' 2>/dev/null || true)" == True && "$(kubectl -n kube-system get pod kube-controller-manager-controlplane -o jsonpath='{.status.conditions[?(@.type=="Ready")].status}' 2>/dev/null || true)" == True ]]; then
      kubectl -n "${Q1_NS}" rollout status deployment/web --timeout=240s
    fi
    sed -i -E 's#^([[:space:]]*- --etcd-servers=)https://127.0.0.1:2379$#\1http://127.0.0.1:2379#' /etc/kubernetes/manifests/kube-apiserver.yaml
    sed -i -E 's#^([[:space:]]*- --)etcd-servers=#\1etcd-server=#' /etc/kubernetes/manifests/kube-apiserver.yaml
    grep -qE -- '- --etcd-server=http://127.0.0.1:2379$' /etc/kubernetes/manifests/kube-apiserver.yaml || { echo "could not break --etcd-servers" >&2; exit 1; }
    sed -i -E 's#^([[:space:]]*- --etcd-cafile=)/etc/kubernetes/pki/etcd/ca.crt$#\1/etc/kubernetes/pki/ca.crt#' /etc/kubernetes/manifests/kube-apiserver.yaml
    grep -qE -- '- --etcd-cafile=/etc/kubernetes/pki/ca.crt$' /etc/kubernetes/manifests/kube-apiserver.yaml || { echo "could not break --etcd-cafile" >&2; exit 1; }
    ;;
  apiserver-admission-plugin)
    kubectl -n "${Q1_NS}" scale deployment/web --replicas=2
    if [[ "$(kubectl -n kube-system get pod kube-scheduler-controlplane -o jsonpath='{.status.conditions[?(@.type=="Ready")].status}' 2>/dev/null || true)" == True && "$(kubectl -n kube-system get pod kube-controller-manager-controlplane -o jsonpath='{.status.conditions[?(@.type=="Ready")].status}' 2>/dev/null || true)" == True ]]; then
      kubectl -n "${Q1_NS}" rollout status deployment/web --timeout=240s
    fi
    sed -i -E 's#^([[:space:]]*- --enable-admission-plugins=[^[:space:]]+)$#\1,PodSecurityPolicy#' /etc/kubernetes/manifests/kube-apiserver.yaml
    grep -qE -- '- --enable-admission-plugins=.*,PodSecurityPolicy$' /etc/kubernetes/manifests/kube-apiserver.yaml || { echo "could not modify /etc/kubernetes/manifests/kube-apiserver.yaml" >&2; exit 1; }
    ;;
  apiserver-etcd-keyfile)
    kubectl -n "${Q1_NS}" scale deployment/web --replicas=2
    if [[ "$(kubectl -n kube-system get pod kube-scheduler-controlplane -o jsonpath='{.status.conditions[?(@.type=="Ready")].status}' 2>/dev/null || true)" == True && "$(kubectl -n kube-system get pod kube-controller-manager-controlplane -o jsonpath='{.status.conditions[?(@.type=="Ready")].status}' 2>/dev/null || true)" == True ]]; then
      kubectl -n "${Q1_NS}" rollout status deployment/web --timeout=240s
    fi
    sed -i -E 's#^([[:space:]]*- --etcd-keyfile=)/etc/kubernetes/pki/apiserver-etcd-client.key$#\1/etc/kubernetes/pki/etcd/apiserver-etcd-client.key#' /etc/kubernetes/manifests/kube-apiserver.yaml
    grep -qE -- '- --etcd-keyfile=/etc/kubernetes/pki/etcd/apiserver-etcd-client.key$' /etc/kubernetes/manifests/kube-apiserver.yaml || { echo "could not modify /etc/kubernetes/manifests/kube-apiserver.yaml" >&2; exit 1; }
    ;;
  apiserver-tls-key-path)
    kubectl -n "${Q1_NS}" scale deployment/web --replicas=2
    if [[ "$(kubectl -n kube-system get pod kube-scheduler-controlplane -o jsonpath='{.status.conditions[?(@.type=="Ready")].status}' 2>/dev/null || true)" == True && "$(kubectl -n kube-system get pod kube-controller-manager-controlplane -o jsonpath='{.status.conditions[?(@.type=="Ready")].status}' 2>/dev/null || true)" == True ]]; then
      kubectl -n "${Q1_NS}" rollout status deployment/web --timeout=240s
    fi
    sed -i -E 's#^([[:space:]]*- --tls-private-key-file=/etc/kubernetes/pki/apiserver)\.key$#\1.pem#' /etc/kubernetes/manifests/kube-apiserver.yaml
    grep -qE -- '- --tls-private-key-file=/etc/kubernetes/pki/apiserver.pem$' /etc/kubernetes/manifests/kube-apiserver.yaml || { echo "could not modify /etc/kubernetes/manifests/kube-apiserver.yaml" >&2; exit 1; }
    ;;
  apiserver-manifest-removed)
    kubectl -n "${Q1_NS}" scale deployment/web --replicas=2
    if [[ "$(kubectl -n kube-system get pod kube-scheduler-controlplane -o jsonpath='{.status.conditions[?(@.type=="Ready")].status}' 2>/dev/null || true)" == True && "$(kubectl -n kube-system get pod kube-controller-manager-controlplane -o jsonpath='{.status.conditions[?(@.type=="Ready")].status}' 2>/dev/null || true)" == True ]]; then
      kubectl -n "${Q1_NS}" rollout status deployment/web --timeout=240s
    fi
    mv /etc/kubernetes/manifests/kube-apiserver.yaml /var/tmp/cka-kube-apiserver.yaml
    [[ ! -f /etc/kubernetes/manifests/kube-apiserver.yaml ]]
    ;;
  apiserver-advertise-address)
    kubectl -n "${Q1_NS}" scale deployment/web --replicas=2
    if [[ "$(kubectl -n kube-system get pod kube-scheduler-controlplane -o jsonpath='{.status.conditions[?(@.type=="Ready")].status}' 2>/dev/null || true)" == True && "$(kubectl -n kube-system get pod kube-controller-manager-controlplane -o jsonpath='{.status.conditions[?(@.type=="Ready")].status}' 2>/dev/null || true)" == True ]]; then
      kubectl -n "${Q1_NS}" rollout status deployment/web --timeout=240s
    fi
    grep -oE -- '--advertise-address=[^[:space:]]+' /etc/kubernetes/manifests/kube-apiserver.yaml | head -1 | sed 's/^--advertise-address=//' > "/var/tmp/cka-q1.advertise"
    sed -i -E 's#^([[:space:]]*- --advertise-address=).*$#\1not-a-valid-ip#' /etc/kubernetes/manifests/kube-apiserver.yaml
    grep -qE -- '- --advertise-address=not-a-valid-ip$' /etc/kubernetes/manifests/kube-apiserver.yaml || { echo "could not modify /etc/kubernetes/manifests/kube-apiserver.yaml" >&2; exit 1; }
    ;;
  apiserver-service-account-key)
    kubectl -n "${Q1_NS}" scale deployment/web --replicas=2
    if [[ "$(kubectl -n kube-system get pod kube-scheduler-controlplane -o jsonpath='{.status.conditions[?(@.type=="Ready")].status}' 2>/dev/null || true)" == True && "$(kubectl -n kube-system get pod kube-controller-manager-controlplane -o jsonpath='{.status.conditions[?(@.type=="Ready")].status}' 2>/dev/null || true)" == True ]]; then
      kubectl -n "${Q1_NS}" rollout status deployment/web --timeout=240s
    fi
    sed -i -E 's#^([[:space:]]*- --service-account-key-file=/etc/kubernetes/pki/sa)\.pub$#\1.pem#' /etc/kubernetes/manifests/kube-apiserver.yaml
    grep -qE -- '- --service-account-key-file=/etc/kubernetes/pki/sa.pem$' /etc/kubernetes/manifests/kube-apiserver.yaml || { echo "could not modify /etc/kubernetes/manifests/kube-apiserver.yaml" >&2; exit 1; }
    ;;
  *)
    echo "unknown fault" >&2
    exit 1
    ;;
esac

case "${Q1_FAULT}" in
  apiserver-etcd-port)
    for _ in $(seq 1 90); do
      [[ "$(curl -sk --max-time 3 https://127.0.0.1:6443/readyz 2>/dev/null || true)" != ok ]] && exit 0
      sleep 2
    done
    echo "the API server is still healthy" >&2
    exit 1
    ;;
  apiserver-etcd-certfile)
    for _ in $(seq 1 90); do
      [[ "$(curl -sk --max-time 3 https://127.0.0.1:6443/readyz 2>/dev/null || true)" != ok ]] && exit 0
      sleep 2
    done
    echo "the API server is still healthy" >&2
    exit 1
    ;;
  apiserver-etcd-flags)
    for _ in $(seq 1 90); do
      [[ "$(curl -sk --max-time 3 https://127.0.0.1:6443/readyz 2>/dev/null || true)" != ok ]] && exit 0
      sleep 2
    done
    echo "the API server is still healthy" >&2
    exit 1
    ;;
  apiserver-admission-plugin)
    for _ in $(seq 1 90); do
      [[ "$(curl -sk --max-time 3 https://127.0.0.1:6443/readyz 2>/dev/null || true)" != ok ]] && exit 0
      sleep 2
    done
    echo "the API server is still healthy" >&2
    exit 1
    ;;
  apiserver-etcd-keyfile)
    for _ in $(seq 1 90); do
      [[ "$(curl -sk --max-time 3 https://127.0.0.1:6443/readyz 2>/dev/null || true)" != ok ]] && exit 0
      sleep 2
    done
    echo "the API server is still healthy" >&2
    exit 1
    ;;
  apiserver-tls-key-path)
    for _ in $(seq 1 90); do
      [[ "$(curl -sk --max-time 3 https://127.0.0.1:6443/readyz 2>/dev/null || true)" != ok ]] && exit 0
      sleep 2
    done
    echo "the API server is still healthy" >&2
    exit 1
    ;;
  apiserver-manifest-removed)
    for _ in $(seq 1 90); do
      [[ "$(curl -sk --max-time 3 https://127.0.0.1:6443/readyz 2>/dev/null || true)" != ok ]] && exit 0
      sleep 2
    done
    echo "the API server is still healthy" >&2
    exit 1
    ;;
  apiserver-advertise-address)
    for _ in $(seq 1 90); do
      [[ "$(curl -sk --max-time 3 https://127.0.0.1:6443/readyz 2>/dev/null || true)" != ok ]] && exit 0
      sleep 2
    done
    echo "the API server is still healthy" >&2
    exit 1
    ;;
  apiserver-service-account-key)
    for _ in $(seq 1 90); do
      [[ "$(curl -sk --max-time 3 https://127.0.0.1:6443/readyz 2>/dev/null || true)" != ok ]] && exit 0
      sleep 2
    done
    echo "the API server is still healthy" >&2
    exit 1
    ;;
esac
